function _zV(ctx, P, fill, stroke = null, lw = 1) { _zPad(ctx, P, true); if (fill) { ctx.fillStyle = fill; ctx.fill(); } if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); } }
